                }
                repeater(Control52)
                {
                    ShowCaption = false;
                    field("Similar Fields Label"; Rec."Similar Fields Label")
                    {
                        ApplicationArea = All;
                        Caption = 'Fields';
                        ToolTip = 'Specifies the number of fields that the data classification will be applied to.';
                        Editable = false;

                        trigger OnDrillDown()
                        begin
                            RunDataClassificationWorksheetForPersonalAndSensitiveDataInTable();
                        end;
                    }
                    field("Status 2"; Rec."Status 2")
                    {
