                begin
                    if Step = Step::Verify then
                        Rec.Reset();
                    NextStep(true);
                end;
            }
            action(ActionFinish)
            {
                ApplicationArea = All;
                Caption = 'Finish';
                ToolTip = 'Finish';
                Enabled = FinishEnabled;
                Image = Approve;
                InFooterBar = true;

                trigger OnAction()
                begin
                    if ShowWorksheet then
                        Page.Run(Page::"Data Classification Worksheet");
                    CurrPage.Close();
                end;
            }
        }
    }

