                            OptionCaption = 'Unclassified,Sensitive,Personal,Company Confidential,Normal';
                        }
                        field(ViewFieldsLbl; ViewFieldsTok)
                        {
                            ApplicationArea = All;
                            ToolTip = 'View a list of fields that are used to post transactions.';
