                            RunDataClassificationWorksheetForTable();
                        end;
                    }
                    field(Status; Rec.Status)
                    {
                        ApplicationArea = All;
                        Editable = false;
                        StyleExpr = StatusStyle;
                        ToolTip = 'Specifies if you have reviewed the classifications that will be applied to the data subjects.';

                        trigger OnDrillDown()
