                        PEPPOLLineInfoProvider: Interface "PEPPOL Line Info Provider";
                    begin
                        PEPPOLLineInfoProvider := GetFormat();
                        PEPPOLLineInfoProvider.GetLinePriceInfo(
                          SalesLine,
                          SalesHeader,
                          InvoiceLinePriceAmount,
                          InvLinePriceAmountCurrencyID,
                          BaseQuantity,
                          UnitCodeBaseQty);
                    end;
                }

                trigger OnAfterGetRecord()
                var
                    IPEPPOLLineInfoProvider: Interface "PEPPOL Line Info Provider";
                begin
                    if not PostedLineIterator.GetNextPostedLineAsSalesLine(PostedSourceLineRecRef, SalesLine) then
                        currXMLport.Break();

                    IPEPPOLLineInfoProvider := GetFormat();
                    IPEPPOLLineInfoProvider.GetLineGeneralInfo(
                      SalesLine,
                      SalesHeader,
                      InvoiceLineID,
                      InvoiceLineNote,
                      InvoicedQuantity,
                      InvoiceLineExtensionAmount,
                      LineExtensionAmountCurrencyID,
                      InvoiceLineAccountingCost);

                    IPEPPOLLineInfoProvider.GetLineUnitCodeInfo(SalesLine, unitCode, DummyVar);
                end;
            }

            trigger OnAfterGetRecord()
            var
                PEPPOL30Common: Codeunit "PEPPOL30 Common";
                IPEPPOLDocumentInfoProvider: Interface "PEPPOL Document Info Provider";
            begin
                if not PostedHeaderIterator.GetNextPostedHeaderAsSalesHeader(PostedSourceRecRef, SalesHeader) then
                    currXMLport.Break();

                PEPPOL30Common.GetTotals(PostedSourceRecRef, PostedSourceLineRecRef, TempVATAmtLine, TempVATProductPostingGroup, GetFormat());

                IPEPPOLDocumentInfoProvider := GetFormat();
                IPEPPOLDocumentInfoProvider.GetGeneralInfoBIS(
                  SalesHeader,
                  ID,
                  IssueDate,
                  InvoiceTypeCode,
                  Note,
                  TaxPointDate,
                  DocumentCurrencyCode,
                  AccountingCost);

                CustomizationID := GetCustomizationID();
                ProfileID := GetProfileID();
            end;
        }
    }

    requestpage
    {

        layout
        {
            area(content)
            {
                group(Control2)
                {
                    ShowCaption = false;
                    field(SalesInvoiceNumber; SalesInvoiceHeader."No.")
                    {
                        ApplicationArea = Basic, Suite;
                        Caption = 'Sales Invoice No.';
                        TableRelation = "Sales Invoice Header";
                        ToolTip = 'Specifies the sales invoice to be exported as a PEPPOL 3.0 document.';
                    }
                }
            }
        }
    }

