                IPEPPOLDocumentInfoProvider.GetGeneralInfoBIS(
                  SalesHeader,
                  ID,
                  IssueDate,
                  InvoiceTypeCode,
                  Note,
                  TaxPointDate,
                  DocumentCurrencyCode,
                  AccountingCost);

                CustomizationID := GetCustomizationID();
                ProfileID := GetProfileID();
            end;
